insert into public.categories (
  project_id, url, name, external_id, parent_external_id, products_count,
  catalog_short_description, catalog_long_description,
  target_keyword, keyword_volume, keyword_difficulty, keyword_intent, keyword_data_at
) values
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/161-bijoux-ambre-femme', 'Bijoux en ambre pour femme', 161, 126, 533, 'Trésor emblématique de notre Maison, les bijoux en ambre pour femme capturent la lumière et reflètent la chaleur d’une résine millénaire. Chaque pièce est façonnée à partir d’un ambre de la mer Baltique, choisi pour sa beauté naturelle et sa singularité. Des créations intemporelles, livrées avec certificat d’authenticité, pour sublimer chaque instant de vie.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/162-bijoux-ambre-homme', 'Bijoux en ambre pour homme', 162, 126, 6, 'Laissez parler la nature avec nos bijoux en ambre pour hommes. Nous vous proposons des bijoux authentiques, parés de morceaux d''ambre de la Baltique, livrés avec leur certificat d''authenticité. Des créations LMDLA en ambre véritable, intemporelles, chaleureuses, pour tous les hommes de caractère qui aiment combiner sobriété et élégance au quotidien.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/163-colliers-ambre', 'Colliers en ambre', 163, 126, 122, 'Les colliers en ambre de LMDLA célèbrent la puissance minérale et la chaleur solaire de l’ambre de la mer Baltique. Laissez cette pierre organique captivante parfaire vos journées, par son éclat unique et intemporel. Symboles de tradition et de savoir-faire, nos colliers en ambre sont accompagnés de leur certificat d’authenticité, pour gâter petits et grands.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/164-bracelets-ambre', 'Bracelets en ambre', 164, 126, 82, 'Nous sommes heureux de vous présenter des bijoux en ambre de qualité, à la fois élégants et intemporels. Chaque perle, aux reflets chauds, conte une histoire différente, née de la mer Baltique. Authentiques et élégants, les bracelets en ambre LMDLA sont des alliés du quotidien et s’offrent comme symboles précieux, avec leur certificat d’authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/165-bagues-ambre', 'Bagues en ambre', 165, 126, 163, 'Les bagues en ambre de LMDLA renferment l’éclat du soleil capturé par le temps. Nous choisissons les plus belles résines minérales, issues de la mer Baltique et certifiées, pour illuminer chaque geste d’une chaleur singulière. Offrir ou porter une bague en ambre, c’est faire le choix d''un bijou intemporel, liant nature et tradition.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/166-boucles-oreilles-ambre', 'Boucles d''oreilles en ambre', 166, 126, 103, 'Découvrez comment une paire de boucles d''oreilles en ambre peut capturer la lumière pour souligner la douceur d''un visage. Chaque création LMDLA, façonnée autour d’un ambre de la mer Baltique, reflète la puissance naturelle des minéraux. Authentiques et raffinées, elles sont comme de petits trésors, accompagnées de leur certificat d’authenticité, à porter fièrement.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/167-pendentif-ambre', 'Pendentif en ambre', 167, 126, 83, 'Choisissez votre pendentif en ambre, amulette symbolique aux doux reflets à porter chaque jour ou cadeau au design raffiné à offrir. Cette résine millénaire captive le regard et sublime vos tenues. LMDLA a fait des pendentifs en ambre certifiés sa spécialité ; des bijoux porteurs d’histoire et de lumière qui se transmettent au fil des générations.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/168-chevaliere-ambre', 'Chevalière en ambre', 168, 126, 3, 'Symbole de caractère et d’identité, la chevalière en ambre associe tradition et singularité. Découvrez des bijoux dans lesquels puissance de la nature et magie du temps qui passe s''entremêlent. Les chevalières en ambre LMDLA, ornées de pierres organiques de la mer Baltique, sont des créations intemporelles que vous n''avez pas fini d''observer !', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/169-bijoux-ambre-vert', 'Bijoux en ambre vert', 169, 126, 20, 'Les bijoux en ambre vert ont été pensés pour les femmes qui souhaitent porter de l''ambre et se parer de reflets singuliers. LMDLA vous dévoile une gamme de bijoux mettant en valeur cette teinte précieuse, aux reflets froids et mystérieux. Nos créations élégantes et originales en ambre vert sont toutes accompagnées d''un certificat d’authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/261-bijoux-ambre-jaune', 'Bijoux en ambre jaune', 261, 126, 15, 'Parcourez nos différents bijoux en ambre jaune, incarnant éclat solaire et douceur naturelle de cette résine au mille visages. La Maison de l''Ambre propose depuis 1973 des créations authentiques, certifiées, sublimées par des métaux précieux. Notre ambre de la mer Baltique vous promet une qualité constante pour des bijoux élégants et singulièrement uniques.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/262-bijoux-ambre-cognac', 'Bijoux en ambre cognac', 262, 126, 415, 'Les bijoux en ambre cognac de La Maison de l’Ambre reflètent la richesse des teintes chaudes et profondes de l’ambre de la mer Baltique. Ils incarnent authenticité, éclat et élégance, que vous optiez pour une parure discrète ou pour une pièce plus imposante. Chaque création à l''authenticité certifiée est la promesse d''un voyage audacieux.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/176-bagues-amethyste', 'Bagues en améthyste', 176, 127, 24, 'Couleur violette intense et douceur délicate : nos bagues en améthyste associent éclat de la nature et talent des équipes LMDLA. Chaque création réalisée dans nos ateliers est unique, pensée pour illuminer vos gestes avec poésie. Fine ou plus marquante, mais toujours certifiée authentique, trouvez la bague en améthyste qui accompagnera vos journées tout en douceur.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/177-bracelets-amethyste', 'Bracelets en améthyste', 177, 127, 14, 'Les bracelets en améthyste de LMDLA dévoilent des nuances violettes profondes, intenses ou plus discrètes. Chaque pierre possède son propre éclat, rendant chaque bijou parfaitement unique. Optez pour un bracelet en améthyste, bijou de caractère à porter pour illuminer vos instants de vie ou symbole de paix et de sérénité à offrir.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/178-colliers-amethyste', 'Colliers en améthyste', 178, 127, 16, 'Parcourez nos différents colliers en améthyste, parcourus de reflets mystérieux semblant capturer la lumière. Les bijoux LMDLA se parent de cette pierre fine violette, réputée pour apporter calme et équilibre, pour des créations uniques. Authentiques et intemporels, nos colliers en améthyste sont livrés avec leur certificat d’authenticité, gage de qualité et de confiance.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/179-boucles-oreilles-amethyste', 'Boucles d''oreilles en améthyste', 179, 127, 30, 'Misez sur une paire de boucles d’oreilles en améthyste et laissez la beauté minérale sublimer votre quotidien. Pierre apaisante par excellence, l''améthyste présente des éclats violets aux reflets mystérieux qui illuminent le visage avec élégance et douceur. Trouvez parmi notre collection de boucles d’oreilles en améthyste celle qui correspond à votre personnalité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/180-pendentifs-amethyste', 'Pendentifs en améthyste', 180, 127, 12, 'Profonds et lumineux, c''est souvent ce que l''on dit de nos pendentifs en améthyste. Choisissez la voie de la tendresse et de la délicatesse de la couleur violette, avec des pierres montées sur d''élégants bijoux signés LMDLA. Symbole d''équilibre et de protection, choisissez le pendentif en améthyste, qui illuminera chaque style, avec douceur et élégance.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/181-bagues-aventurine', 'Bagues en aventurine', 181, 129, 9, 'Porter des bagues en aventurine, c’est glisser à son doigt un éclat de nature. Son vert tendre rappelle les feuillages au soleil, pour un vent de fraîcheur dans votre quotidien. LMDLA transforme cette pierre authentique en bijoux certifiés, alliant simplicité et élégance. Trouvez une bague en aventurine à votre image, symbole de paix et d''équilibre.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/182-colliers-aventurine', 'Colliers en aventurine', 182, 129, 7, 'Délicats et lumineux, les colliers en aventurine La Maison de l’Ambre reflètent fraîcheur et vitalité. Nos créations mettent en valeur cette pierre naturelle verte et singulière au nom poétique. En lithothérapie, les colliers en aventurine sont réputés pour leurs potentiels bienfaits de confiance et d’apaisement. Choisissez donc le vôtre, livré avec son certificat d''authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/183-pendentifs-aventurine', 'Pendentifs en aventurine', 183, 129, 2, 'Laissez nos pendentifs en aventurine vous envelopper de leurs nuances vertes, tendres et douces ou plus éclatantes. LMDLA vous présente des bijoux fins et élégants, ornés de cette pierre au nom poétique, associés à la confiance en soi. Nos pendentifs en aventurine se portent comme une signature personnelle ou s’offrent comme un présent intemporel et authentique.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/184-boucles-oreilles-aventurine', 'Boucles d''oreilles en aventurine', 184, 129, 11, 'Offrez des boucles d’oreilles en aventurine à vos proches, une pierre vert tendre, que l''on associe souvent à la confiance en soi. LMDLA vous délivre chaque bijou avec son certificat d''authenticité. Romantiques, modernes ou raffinées, nos boucles d’oreilles en aventurine sont des bijoux intemporels, parfaits à porter chaque jour ou à offrir comme déclaration précieuse.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/185-bracelets-labradorite', 'Bracelets en labradorite', 185, 134, 3, 'Les bracelets en labradorite sont la promesse d’un éclat unique : ses reflets irisés oscillent entre gris profond et lueurs bleutées. Authentiques et raffinés, les bracelets en labradorite LMDLA ajoutent mystère et élégance à vos tenues, tout en captivant les regards. Bijoux intemporels et certifiés, ils se portent au quotidien ou s’offrent comme de précieux cadeaux.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/186-bagues-labradorite', 'Bagues en labradorite', 186, 134, 10, 'Les bagues en labradorite de LMDLA reflètent la magie des horizons changeants, où le bleu profond de la mer rencontre les lueurs célestes. Nos créations vous dévoilent des reflets irisés uniques, pour porter à vos doigts le plus beau de la nature. Réputées pour leurs potentiels bienfaits de protection, les bagues en labradorite vous accompagneront durablement.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/187-colliers-labradorite', 'Colliers en labradorite', 187, 134, 5, 'Les colliers en labradorite marquent toujours les esprits par leurs éclats irisés et par la subtilité de leurs nuances bleutées. C''est une pierre fascinante, réputée pour ses potentiels bienfaits protecteurs, qui confère de la brillance et de l''authenticité à toutes les tenues. Chez LMDLA, nous créons des bijoux certifiés, à la fois lumineux et singuliers.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/188-pendentifs-labradorite', 'Pendentifs en labradorite', 188, 134, 8, 'Jouez la carte du mystère avec nos pendentifs en labradorite. Cette pierre symbole de confiance en soi et de protection, aux reflets changeants, presque surréalistes, captive les regards. Chez LMDLA, nous faisons le choix de la qualité et de la singularité avec nos pendentifs fins ou plus imposants en labradorite, livrés avec un certificat d''authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/189-boucles-oreilles-labradorite', 'Boucles d''oreilles en labradorite', 189, 134, 13, 'Choisissez la voie de la tendresse minérale avec les boucles d’oreilles en labradorite LMDLA. Nous vous dévoilons des bijoux fins, légers, qui captent et renvoient la lumière par leurs reflets irisés uniques. Livrées avec un certificat d''authenticité, nos boucles d’oreilles en labradorite sont des créations originales et subtiles qui se marient avec tous les styles.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/155-bijoux-signe-astrologique', 'Bijoux signe astrologique', 155, 136, 1052, 'Exprimez votre personnalité et votre caractère avec nos bijoux signe astrologique. LMDLA rassemble des créations originales, parfois ornées de pierres naturelles réputées en lithothérapie pour leurs potentiels bienfaits. Des bijoux astrologiques porteurs de sens, qui associent style et symbolique céleste pour accompagner et vous porter au quotidien, toujours livrés avec un certificat d''authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/156-bijoux-pierre-naissance', 'Bijoux pierre de naissance', 156, 136, 265, 'Offrez ou portez un bijou pierre de naissance : une création personnalisée, élégante et symbolique, signée La Maison de l’Ambre. Notre maison fait le choix de la qualité depuis 1973, pour des créations associant qualité et authenticité. Trouvez le bijou orné de votre pierre de naissance, reflet intime de la nature et du temps qui passe.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/157-bijoux-chakras', 'Bijoux chakras', 157, 136, 902, 'Les bijoux chakras de La Maison de l’Ambre associent pierres naturelles et symbolique spirituelle. Chaque pierre est réputée en lithothérapie pour ses potentiels bienfaits énergétiques, liés à l’harmonie des centres du corps. Découvrez alors nos créations uniques qui allient esthétique, équilibre et profondeur symbolique, des bijoux naturels de grande qualité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/190-bracelets-opale', 'Bracelets en opale', 190, 140, 4, 'Laissez les bracelets en opale vous envelopper de leur éclat tendre et mystérieux. Chaque bracelet en opale LMDLA met en valeur cette pierre précieuse emblématique, symbole de raffinement et d’authenticité. Découvrez des bijoux élégants et intemporels capables de compléter toutes les tenues avec une pointe de lumière, livrés avec leurs certificats d''authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/191-bagues-opale', 'Bagues en opale', 191, 140, 50, 'Ce sont des pierres aux mille reflets qui ornent les bagues en opale LMDLA. Cette pierre précieuse qui symbolise l’intuition et la créativité confère à nos bagues éclat et raffinement. Nos bagues en opale, lumineuses et poétiques, délivrées avec un certificat d''authenticité, vous rappellent que la puissance de la nature est à portée de main.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/192-colliers-opale', 'Colliers en opale', 192, 140, 12, 'Les colliers en opale LMDLA, sont comme des fragments d''irréel autour de votre cou. Nous vous dévoilons des colliers originaux, fins et discrets ou plus majestueux, sublimés par cette pierre précieuse associée à la créativité. Nos colliers en opale, avec leurs éclats changeants et mystérieux vous sont livrés avec un certificat d''authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/193-pendentifs-opale', 'Pendentifs en opale', 193, 140, 11, 'Les pendentifs en opale de LMDLA fascinent par leurs aspects changeants, ondoyants et éclatants. Fin et moderne ou romantique tout en rondeur, définissez le pendentif en opale qui viendra parfaire vos tenues ; un certificat d''authenticité accompagne chaque bijou. L’opale est une pierre précieuse à laquelle on associe les notions de créativité et d’intuition.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/194-boucles-oreilles-opale', 'Boucles d''oreilles en opale', 194, 140, 12, 'Les boucles d''oreille en opale sont un cadeau précieux et discret, incarnant l''élégance, la singularité et la puissance de la nature. Retrouvez la beauté de l''opale, avec ses éclats changeants si particuliers, montée sur des boucles d''oreilles de qualité LMDLA. Symbole de créativité et d''intuition, nos bijoux sont délivrés avec leur certificat d''authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/195-bracelets-pierre-lune', 'Bracelets en pierre de lune', 195, 141, 6, 'Les bracelets en pierre de lune sont une ode à la douceur et au mystère. Leurs reflets nacrés et changeants, qui rappellent la beauté d''un ciel étoilé, en font des bijoux presque envoûtants. LMDLA vous présente des bracelets en pierre de lune de qualité, certifiés, d''élégants talismans à porter ou à offrir comme de précieux trésors.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/196-bagues-pierre-lune', 'Bagues en pierre de lune', 196, 141, 9, 'Élégantes et délicates, nos bagues en pierre de lune vous annoncent des instants poétiques. La Maison de l''Ambre a rassemblé dans ses créations certifiées l''éclat nacré de cette pierre originale et le savoir-faire de bijoutiers passionnés. Choisissez la bague en pierre de lune qui reflètera votre féminité, associée à la clairvoyance et à l''harmonie.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/197-colliers-pierre-lune', 'Colliers en pierre de lune', 197, 141, 12, 'Les colliers en pierre de lune vous présentent leur éclat nacré et leur charme intemporel. Chaque création signée LMDLA capte subtilement la lumière, révélant une pierre symbole de féminité et d’harmonie. Raffinés et uniques, nos colliers en pierre de lune sont des bijoux du quotidien, des présents précieux offerts avec leur certificat d''authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/198-pendentifs-pierre-lune', 'Pendentifs en pierre de lune', 198, 141, 1, 'Quelle que soit leur forme, nos pendentifs en pierre de lune vous dévoilent un monde de douceur. Cette pierre au nom réconfortant, dotée de reflets nacrés changeants, incarne la féminité et l’harmonie intérieure. Trouvez le pendentif en pierre de lune LMDLA qui comblera vos envies et illuminera vos tenues avec élégance, livré avec son certificat d’authenticité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/199-boucles-oreilles-pierre-lune', 'Boucles d''oreilles en pierre de lune', 199, 141, 11, 'Laissez nos boucles d’oreilles en pierre de lunes vous captiver, entre éclat nacré et provenance presque mystique. Elles incarnent la délicatesse et la féminité, parée d''une pierre symbolisant l’harmonie intérieure. Trouvez les boucles d''oreilles en pierre de lunes raffinées et intemporelles qui mettront une pincée d''onirisme dans votre quotidien.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/200-colliers-quartz', 'Colliers en quartz', 200, 143, 27, 'Les colliers en quartz sont à l''image de la beauté de la nature : colorés, robustes et lumineux. Fumé, rosé ou ensoleillé, le quartz se pare de mille nuances pour accompagner judicieusement toutes les tenues. Trouvez parmi les colliers LMDLA en quartz certifiés, le bijou raffiné qui sublimera votre port de tête, avec grâce et simplicité.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/201-pendentifs-quartz', 'Pendentifs en quartz', 201, 143, 12, 'Les pendentifs en quartz de La Maison de l’Ambre sont des talismans aux mille reflets. Découvrez des pierres aux teintes variées, taillées pour que chaque facette renvoie un maximum de lumière, mettant en valeur votre port de tête. Symboles d''équilibre et d''énergie, nos pendentifs en quartz certifiés sont un cadeau aussi élégant qu''intemporel.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/202-boucles-oreilles-quartz', 'Boucles d''oreilles en quartz', 202, 143, 27, 'Portez ou offrez des boucles d’oreilles en quartz, éclats cristallins qui semblent capter la lumière pour illuminer votre visage. Délicates et lumineuses, elles évoquent la pureté et sont réputées pour leurs possibles bienfaits énergétiques. Chaque paire de boucles d’oreilles en quartz LMDLA devient un bijou raffiné, à la fois intemporel et empreint de poésie.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/203-bracelets-quartz', 'Bracelets en quartz', 203, 143, 11, 'Succombez à l''éclat sans pareil de nos bracelets en quartz, à la fois beaux et discrets. LMDLA sait combien le quartz, réputé pour ses potentiels bienfaits énergétiques, peut mettre en valeur votre poignet. Retrouvez plusieurs modèles de bracelet en quartz délicats, élégants et lumineux, délivrés avec leur garantie d’authenticité', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/204-bijoux-quartz-fume', 'Bijoux en quartz fumé', 204, 143, 11, 'Les bijoux en quartz fumé de LMDLA dévoilent des teintes envoûtantes, du brun naturel au gris profond, comme des éclats de brume capturés dans la pierre. Mystérieux et élégants, nos bijoux en quartz fumé sont des créations raffinées, sophistiquées et intemporelles. Des bijoux à la fois faciles à porter au quotidien et capables de constituer des cadeaux uniques.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/205-bijoux-quartz-rose', 'Bijoux en quartz rose', 205, 143, 78, 'Saviez-vous que les bijoux en quartz rose, délicats et lumineux, pouvaient apporter une touche de douceur à chaque tenue ? Symbole d’amour et de sérénité, le quartz rose séduit par ses teintes douces et ses reflets subtils. Retrouvez les créations LMDLA qui transforment cette délicate pierre naturelle en bijoux modernes et raffinés, des cadeaux uniques !', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/214-bagues-quartz', 'Bagues en quartz', 214, 143, 23, 'Découvrez notre collection de bagues en quartz à la fois modernes et naturelles. Cette pierre qui incarne pureté et élégance, apporte aux bijoux LMDLA un côté lumineux et sophistiqué. Des bagues en quartz raffinées, conçues pour sublimer chaque geste du quotidien, ou pour offrir un brin de lumière et d''énergie à vos proches.', null, null, null, null, null, null),
('dd5cc453-308b-4b24-822d-ef70e77b4438'::uuid, 'https://lamaisondelambre.com/fr/206-bagues-turquoise', 'Bagues en turquoise', 206, 147, 6, 'Laissez nos bagues en turquoise vous séduire, par leur éclat naturel et leur originalité. Chaque création LMDLA met en valeur la beauté vibrante de cette pierre bleue emblématique, livrée avec son certificat d''authenticité. Associées à la protection, à la créativité et à l''harmonie, nos bagues en turquoise sont des bijoux lumineux et intemporels.', null, null, null, null, null, null)
